import { useState, useEffect } from 'react';
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : initialValue;
  });
  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);
  return [value, setValue] as const;
}

import { GoogleGenAI } from '@google/genai';
import OpenAI from 'openai';

export interface AIMessage {
  role: 'system' | 'user' | 'assistant';
  content: string;
}

export interface AICompletionOptions {
  temperature?: number;
  maxTokens?: number;
  responseFormat?: 'text' | 'json_object';
}

export interface AIProviderAdapter {
  generateCompletion(messages: AIMessage[], options?: AICompletionOptions): Promise<string>;
}

export class OpenAIAdapter implements AIProviderAdapter {
  private client: OpenAI;
  private model: string;

  constructor(apiKey: string, model: string = 'gpt-4o') {
    this.client = new OpenAI({ apiKey });
    this.model = model;
  }

  async generateCompletion(messages: AIMessage[], options?: AICompletionOptions): Promise<string> {
    const response = await this.client.chat.completions.create({
      model: this.model,
      messages,
      temperature: options?.temperature ?? 0.7,
      max_tokens: options?.maxTokens,
      response_format: options?.responseFormat === 'json_object' ? { type: 'json_object' } : undefined,
    });
    return response.choices[0]?.message?.content || '';
  }
}

export class GeminiAdapter implements AIProviderAdapter {
  private ai: GoogleGenAI;
  private model: string;

  constructor(apiKey: string, model: string = 'gemini-2.5-flash') {
    this.ai = new GoogleGenAI({ apiKey });
    this.model = model;
  }

  async generateCompletion(messages: AIMessage[], options?: AICompletionOptions): Promise<string> {
    const systemInstruction = messages.find(m => m.role === 'system')?.content;
    const userMessages = messages.filter(m => m.role !== 'system');

    const contents = userMessages.map(m => ({
      role: m.role === 'assistant' ? 'model' : 'user',
      parts: [{ text: m.content }]
    }));

    const response = await this.ai.models.generateContent({
      model: this.model,
      contents,
      config: {
        systemInstruction,
        temperature: options?.temperature ?? 0.7,
        maxOutputTokens: options?.maxTokens,
        responseMimeType: options?.responseFormat === 'json_object' ? 'application/json' : 'text/plain',
      }
    });
    return response.text || '';
  }
}

export class AIProviderFactory {
  static getProvider(providerName: 'openai' | 'gemini', apiKey: string, model?: string): AIProviderAdapter {
    switch (providerName) {
      case 'openai':
        return new OpenAIAdapter(apiKey, model);
      case 'gemini':
        return new GeminiAdapter(apiKey, model);
      default:
        throw new Error(`Unsupported AI provider: ${providerName}`);
    }
  }
}

import { PrismaClient } from '@prisma/client';

export interface DocumentChunkSearchResult {
  id: string;
  documentId: string;
  content: string;
  similarity: number;
}

export class VectorSearchRetrievalService {
  constructor(private prisma: PrismaClient) {}

  async findRelevantContext(queryEmbedding: number[], studyMaterialId: string, matchThreshold: number = 0.75, matchCount: number = 5): Promise<DocumentChunkSearchResult[]> {
    const vectorString = `[${queryEmbedding.join(',')}]`;

    // Execute raw SQL query using PostgreSQL pgvector extension cosine distance operator (<=>)
    const results = await this.prisma.$queryRaw<DocumentChunkSearchResult[]> `
      SELECT 
        id,
        "documentId",
        content,
        1 - (embedding <=> ${vectorString}::vector) as similarity
      FROM "DocumentChunk"
      WHERE "documentId" = ${studyMaterialId}
        AND 1 - (embedding <=> ${vectorString}::vector) > ${matchThreshold}
      ORDER BY similarity DESC
      LIMIT ${matchCount};
    `;

    return results;
  }

  async constructAugmentedPrompt(query: string, queryEmbedding: number[], studyMaterialId: string): Promise<string> {
    const relevantChunks = await this.findRelevantContext(queryEmbedding, studyMaterialId);

    const contextText = relevantChunks.map(chunk => chunk.content).join('\n\n');

    return `You are an AI study assistant. Answer the student's question accurately using ONLY the provided context extracted from their study materials.

Context Materials:
${contextText}

Student Question: ${query}

Answer:`;
  }
}
